import{actionIcon,actionLabel}from './action-icons.js';
import{read,write}from './storage.js';
import{esc,toast}from './ui.js';
import{UMRAH_EDITION,umrahSources,umrahHistory,umrahSteps,pilgrimTips,validUmrahProgress,umrahRoute}from './umrah-content.js';
import{umrahIllustration}from './umrah-illustrations.js';
import{scheduleSources,schedulePrayers,imamLabel,saudiDay,scheduleTime,validScheduleMonth,validScheduleDay,validateHaramainSchedule,scheduleForDay,scheduleDays}from './haramain-schedule.js';
let generation=0,controller=null,snapshot=null;
const saved=()=>{const value=read('umrah-progress',null);return validUmrahProgress(value)?value:null};
const link=(view,label)=>`<a class="umrah-link" href="#umrah?view=${view}">${label}${actionIcon('next')}</a>`;
const sources=refs=>`<details class="umrah-sources"><summary>Источники</summary>${refs.map(id=>umrahSources[id]).filter(Boolean).map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.label)} ${actionIcon('external')}</a>`).join('')}</details>`;
const figure=step=>`<figure>${umrahIllustration(step.image)}<figcaption>${esc(step.caption)}</figcaption></figure>`;
const head=(title,back='#umrah',label='Умра')=>`<header class="umrah-head"><a class="umrah-back" href="${back}"><span aria-hidden="true">‹</span> ${label}</a><h1>${esc(title)}</h1></header>`;
function save(index,complete=saved()?.complete||false){if(!write('umrah-progress',{edition:UMRAH_EDITION,index,complete}))toast('Не удалось сохранить место урока')}
function overview(){const progress=saved();return `${head('Умра','#knowledge','Знания')}<div class="umrah-hero">${umrahIllustration('arrival')}<span class="knowledge-eyebrow">ПУТЬ К ЗАПОВЕДНОЙ МЕЧЕТИ</span><h2>От намерения до завершения</h2><p>Короткие уроки, наглядные схемы и памятка для поездки.</p><a class="button" href="#umrah?step=${progress&&!progress.complete?umrahSteps[progress.index].id:'prepare'}">${progress?progress.complete?'Повторить урок':'Продолжить · шаг '+(progress.index+1):'Начать · 10 шагов'}</a>${progress?.complete?'<span class="umrah-done">Урок пройден</span>':''}</div><nav class="umrah-links" aria-label="Разделы Умры">${link('history','История Умры')}${link('tips','Памятка паломника')}${link('imams','Имамы Мекки и Медины')}</nav><details class="umrah-curriculum"><summary>Все этапы <span>10</span></summary>${umrahSteps.map((row,index)=>`<a href="#umrah?step=${row.id}"><span>${String(index+1).padStart(2,'0')}</span>${esc(row.title)}</a>`).join('')}</details><p class="umrah-footnote">Порядок обрядов — по хадисам и руководству Министерства хаджа и Умры.</p>`}
function lesson(index){const step=umrahSteps[index];save(index);return `${head(step.chapter)}<div class="umrah-progress" aria-label="Шаг ${index+1} из ${umrahSteps.length}"><span>Шаг ${index+1} из ${umrahSteps.length}</span><span>${Math.round((index+1)/umrahSteps.length*100)}%</span><div><i style="width:${(index+1)/umrahSteps.length*100}%"></i></div></div><article class="umrah-lesson">${figure(step)}<h2>${esc(step.title)}</h2>${step.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${step.formula?`<div class="umrah-formula"><p class="umrah-arabic" lang="ar" dir="rtl">${esc(step.formula.arabic)}</p><p>${esc(step.formula.transcription)}</p><p class="umrah-meaning">${esc(step.formula.meaning)}</p></div>`:''}${step.note?`<p class="umrah-note">${esc(step.note)}</p>`:''}${step.detail?`<details class="umrah-detail"><summary>${esc(step.detail.title)}</summary><p>${esc(step.detail.text)}</p></details>`:''}${sources(step.refs)}</article><nav class="umrah-step-nav" aria-label="Переход по уроку">${index?`<a class="button secondary" href="#umrah?step=${umrahSteps[index-1].id}">Назад</a>`:'<a class="button secondary" href="#umrah">К разделу</a>'}${index<umrahSteps.length-1?`<a class="button" href="#umrah?step=${umrahSteps[index+1].id}">Далее ${actionIcon('next')}</a>`:'<a id="umrah-complete" class="button" href="#umrah?view=complete">Завершить урок</a>'}</nav>`}
function history(){return `${head('История Умры')}${umrahHistory.map((row,index)=>`<article class="umrah-story">${umrahIllustration(['arrival','safa','miqat'][index])}<h2>${esc(row.title)}</h2><p>${esc(row.text)}</p>${sources(row.refs)}</article>`).join('')}${link('home','К уроку Умры')}`.replace('#umrah?view=home','#umrah')}
function tips(){return `${head('Памятка паломника')}<p class="umrah-intro">Что пригодится в дороге и в мечети.</p>${pilgrimTips.map((row,index)=>`<details class="umrah-tip" ${index===0?'open':''}><summary>${esc(row.title)}</summary><div><p>${esc(row.text)}</p>${sources(row.refs)}</div></details>`).join('')}<a class="button secondary umrah-official" href="${umrahSources.nusuk.url}" target="_blank" rel="noopener noreferrer">Открыть Nusuk ${actionIcon('external')}</a>`}
function complete(){return `${head('Урок завершён')}<div class="umrah-hero">${umrahIllustration('finish')}<h2>Порядок Умры изучен</h2><p>Вы можете повторить любой этап или открыть памятку перед поездкой.</p><a class="button" href="#umrah?view=tips">Памятка паломника</a><a class="umrah-back" href="#umrah">К разделу Умры</a></div>`}
function monthTitle(month){return new Intl.DateTimeFormat('ru-RU',{timeZone:'UTC',month:'long',year:'numeric'}).format(new Date(month+'-01T12:00:00Z'))}
function scheduleHeader(){return `${head('Имамы Мекки и Медины')}<p class="umrah-intro">Записи официального портала двух святынь.</p>`}
function scheduleView(route,data){
 const today=saudiDay(Date.now()),month=validScheduleMonth(route.month)?route.month:today.slice(0,7);
 const available=[...new Set([today.slice(0,7),month,...data.rows.map(row=>row.day.slice(0,7))])].sort();
 const days=scheduleDays(data,route.mosque,month),day=validScheduleDay(route.day)&&days.includes(route.day)?route.day:days.includes(today)?today:days.at(-1)||month+'-01';
 const rows=scheduleForDay(data,route.mosque,day);
 const stale=Date.now()-Date.parse(data.fetchedAt)>2*86400000;
 const dateLabel=new Intl.DateTimeFormat('ru-RU',{timeZone:'Asia/Riyadh',day:'numeric',month:'long'}).format(new Date(day+'T12:00:00+03:00'));
 return `${scheduleHeader()}<div class="umrah-mosques" role="group" aria-label="Мечеть">${[['mecca','Мекка'],['madinah','Медина']].map(([id,label])=>`<a class="${route.mosque===id?'active':''}" ${route.mosque===id?'aria-current="true"':''} href="#umrah?view=imams&mosque=${id}&month=${month}">${label}</a>`).join('')}</div><div class="umrah-schedule-filters"><label>Месяц<select id="umrah-month">${available.map(value=>`<option value="${value}" ${month===value?'selected':''}>${esc(monthTitle(value))}</option>`).join('')}</select></label><label>Дата<select id="umrah-day" ${days.length?'':'disabled'}>${days.length?days.map(value=>`<option value="${value}" ${day===value?'selected':''}>${Number(value.slice(8))}</option>`).join(''):'<option>Нет данных</option>'}</select></label></div><p class="umrah-schedule-note">Время Мекки и Медины · UTC+3</p><section class="umrah-schedule-list" aria-label="Расписание на ${esc(dateLabel)}">${rows.length?`<h2>${esc(dateLabel)}</h2>${Object.entries(schedulePrayers).map(([key,name])=>{const row=rows.find(value=>value.prayer===key),jumuah=key==='dhuhr'&&new Date(day+'T12:00:00Z').getUTCDay()===5;return `<div class="umrah-schedule-row"><div><strong>${jumuah?'Джума':name}</strong><span dir="auto">${row?esc(imamLabel(row.imam)):'Не опубликовано'}</span></div><time>${row?scheduleTime(row.at):'—'}</time></div>`}).join('')}`:'<div class="umrah-schedule-empty"><h2>Даты пока не опубликованы</h2><p>Для этого месяца на официальном портале нет записей. Выберите другой месяц или откройте источник.</p></div>'}</section><p class="umrah-footnote">Отображаются только опубликованные записи, а не предполагаемые назначения. В выбранном месяце доступны ${days.length} ${days.length===1?'дата':days.length<5&&days.length>1?'даты':'дат'}.</p><p class="umrah-snapshot-date ${stale?'stale':''}">Данные от ${esc(new Intl.DateTimeFormat('ru-RU',{timeZone:'Asia/Riyadh',day:'numeric',month:'long',year:'numeric'}).format(new Date(data.fetchedAt)))}${stale?' · проверьте свежие записи в источнике':''}</p><a class="button secondary umrah-official" href="${scheduleSources[route.mosque]}" target="_blank" rel="noopener noreferrer">Официальный портал ${actionIcon('external')}</a>`;
}
function bindSchedule(host,route){host.querySelector('#umrah-month')?.addEventListener('change',event=>{location.hash='umrah?view=imams&mosque='+route.mosque+'&month='+event.target.value});host.querySelector('#umrah-day')?.addEventListener('change',event=>{location.hash='umrah?view=imams&mosque='+route.mosque+'&month='+host.querySelector('#umrah-month').value+'&day='+event.target.value})}
export function stopUmrah(){generation++;controller?.abort();controller=null;document.body.classList.remove('umrah-focus')}
export async function showUmrah(host){
 stopUmrah();const request=generation,hash=location.hash,route=umrahRoute(hash);
 document.body.classList.toggle('umrah-focus',route.view==='lesson');
 host.innerHTML='<section class="umrah-page"></section>';const page=host.querySelector('.umrah-page');
 if(route.view==='lesson'){page.innerHTML=lesson(route.step);page.querySelector('#umrah-complete')?.addEventListener('click',()=>save(umrahSteps.length-1,true));return}
 if(route.view==='history'){page.innerHTML=history();return}
 if(route.view==='tips'){page.innerHTML=tips();return}
 if(route.view==='complete'){page.innerHTML=complete();return}
 if(route.view!=='imams'){page.innerHTML=overview();return}
 page.innerHTML=scheduleHeader()+'<p role="status">Загружаем опубликованные записи…</p>';
 const pending=new AbortController();controller=pending;
 const timer=setTimeout(()=>pending.abort(),10000);
 const current=()=>request===generation&&hash===location.hash;
 try{
  if(!snapshot){const response=await fetch('./data/haramain-schedule.json',{signal:pending.signal,cache:'no-cache'});if(!response.ok)throw Error('Schedule unavailable');snapshot=validateHaramainSchedule(await response.json())}
  if(!current())return;
  page.innerHTML=scheduleView(route,snapshot);bindSchedule(page,route);
 }catch{if(current()){page.innerHTML=scheduleHeader()+`<p role="status">Не удалось загрузить записи. Подключитесь к интернету и попробуйте снова.</p><button class="button secondary" id="umrah-retry">Повторить</button><a class="umrah-link" href="${scheduleSources[route.mosque]}" target="_blank" rel="noopener noreferrer">Официальный портал ${actionIcon('external')}</a>`;page.querySelector('#umrah-retry').onclick=()=>showUmrah(host)}}finally{clearTimeout(timer);if(controller===pending)controller=null}
}
